def build_agent(sandbox):
    # Base anchored at (-2.0, 0.0)
    base = sandbox.add_anchored_base(x=-2.0, y=0.0, width=0.5, height=0.3, density=400.0)

    # Horizontal arm: 1.5m width, 0.5m height, centered at (-2.0, 0.0)
    horizontal_arm = sandbox.add_beam(x=-2.0, y=0.0, width=1.5, height=0.5, angle=0, density=300.0)

    # Joint between base and horizontal arm at (-2.0, 0.0)
    joint1 = sandbox.add_revolute_joint(
        body_a=base, body_b=horizontal_arm, 
        anchor_point=(-2.0, 0.0), 
        enable_motor=True, motor_speed=0.0, max_motor_torque=150.0
    )

    # Vertical arm: 0.3m width, 1.5m height, centered at (-1.25, 0.0)
    vertical_arm = sandbox.add_beam(x=-1.25, y=0.0, width=0.3, height=1.5, angle=0, density=300.0)

    # Joint between horizontal and vertical arm at (-1.25, 0.0)
    joint2 = sandbox.add_revolute_joint(
        body_a=horizontal_arm, body_b=vertical_arm, 
        anchor_point=(-1.25, 0.0), 
        enable_motor=True, motor_speed=0.0, max_motor_torque=150.0
    )

    # Scoop: 0.5m width, 1.5m height, attached to vertical arm at (-1.25, 0.75)
    scoop = sandbox.add_scoop(x=-1.25, y=0.75, width=0.5, height=1.5, density=280.0)

    # Joint between vertical arm and scoop at (-1.25, 0.75)
    joint3 = sandbox.add_revolute_joint(
        body_a=vertical_arm, body_b=scoop, 
        anchor_point=(-1.25, 0.75), 
        enable_motor=True, motor_speed=0.0, max_motor_torque=150.0
    )

    return horizontal_arm

def agent_action(sandbox, agent_body, step_count):
    # Find all joints connected to the horizontal arm
    joints = []
    for joint in sandbox.world.joint_list:
        if joint.body_a == agent_body or joint.body_b == agent_body:
            joints.append(joint)

    # Identify the relevant joints
    joint1 = joints[0]  # Base to horizontal arm
    joint2 = joints[1]  # Horizontal to vertical arm

    # Determine vertical arm body
    if joint2.body_a == agent_body:
        vertical_arm = joint2.body_b
    else:
        vertical_arm = joint2.body_a

    # Get current angles
    horizontal_angle = agent_body.angle
    vertical_angle = vertical_arm.angle

    # Control logic based on phase
    if step_count % 100 == 0:
        # Phase 1: Scoop from pit
        if horizontal_angle < 0.5:
            joint1.motorSpeed = 0.2  # Rotate horizontal arm right
        else:
            if vertical_angle > -1.57:
                joint2.motorSpeed = -0.2  # Lower vertical arm
            else:
                joint2.motorSpeed = 0.0
    elif step_count % 200 == 0:
        # Phase 2: Lift over wall
        if horizontal_angle > -1.57:
            joint1.motorSpeed = -0.2  # Rotate horizontal arm left
        else:
            if vertical_angle < 1.57:
                joint2.motorSpeed = 0.2  # Raise vertical arm
            else:
                joint2.motorSpeed = 0.0
    elif step_count % 300 == 0:
        # Phase 3: Dump into hopper
        if vertical_angle > 0.0:
            joint2.motorSpeed = -0.2  # Lower vertical arm to dump
        else:
            joint2.motorSpeed = 0.0
    else:
        # Stop movement
        joint1.motorSpeed = 0.0
        joint2.motorSpeed = 0.0

